# 21-30e GREENTE (база ANESCOM_FIX): банковские документы по счетам организации и проводки БУ по 1030/1021/1050.
for dn in ("ПоступлениеБезналичныхДенежныхСредств", "СписаниеБезналичныхДенежныхСредств"):
    for r in q(f"""ВЫБРАТЬ Д.БанковскийСчет КАК Б, Д.Проведен КАК П, ГОД(Д.Дата) КАК Г, КОЛИЧЕСТВО(*) КАК Н, СУММА(Д.СуммаДокумента) КАК С
ИЗ Документ.{dn} КАК Д ГДЕ НЕ Д.ПометкаУдаления И Д.Дата >= &Н И Д.Организация.Наименование ПОДОБНО "%GREENTE%"
СГРУППИРОВАТЬ ПО Д.БанковскийСчет, Д.Проведен, ГОД(Д.Дата)""", Н=datetime.datetime(2025, 1, 1, 5)):
        print(f"{dn[:22]:<22} {s(r['Б'])[:40]:<40} {r['Г']} пров={r['П']}: {r['Н']:>5} док. {r['С'] or 0:>18,.2f}")
for r in q("""ВЫБРАТЬ Т.Счет.Код КАК Сч, Т.Субконто1 КАК С, СУММА(Т.СуммаОборотДт) КАК Д, СУММА(Т.СуммаОборотКт) КАК К
ИЗ РегистрБухгалтерии.{REG}.Обороты(&Н, &К, , Счет.Код В ("1030", "1050", "1021"), , Организация.Наименование ПОДОБНО "%GREENTE%", , ) КАК Т СГРУППИРОВАТЬ ПО Т.Счет.Код, Т.Субконто1""",
           Н=datetime.datetime(2025, 1, 1, 5), К=datetime.datetime(2026, 10, 26, 4, 59)):
    print(f"  БУ {r['Сч']} {s(r['С'])[:45]:<45} Дт {r['Д'] or 0:>18,.2f} Кт {r['К'] or 0:>18,.2f}")
